import React, { useState, useEffect, useRef } from 'react';

const MapView = ({ properties, focusId }) => {
  const mapRef = useRef(null);
  const mapInstance = useRef(null);
  const markersRef = useRef([]);
  const userMarkerRef = useRef(null);

  useEffect(() => {
    // تحميل ملفات Leaflet (CSS & JS) من CDN
    if (!document.getElementById('leaflet-css')) {
      const link = document.createElement('link');
      link.id = 'leaflet-css';
      link.rel = 'stylesheet';
      link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      document.head.appendChild(link);
    }

    if (!window.L) {
      const script = document.createElement('script');
      script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
      script.async = true;
      script.onload = initMap;
      document.body.appendChild(script);
    } else {
      initMap();
    }

    return () => {
      if (mapInstance.current) {
        mapInstance.current.remove();
        mapInstance.current = null;
      }
    };
  }, []);

  const initMap = () => {
    if (!mapRef.current || mapInstance.current || !window.L) return;

    const defaultLocation = [30.0444, 31.2357]; // القاهرة
    const map = window.L.map(mapRef.current).setView(defaultLocation, 10);

    window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(map);

    mapInstance.current = map;
    updateMarkers();
  };

  const updateMarkers = () => {
    if (!mapInstance.current || !window.L) return;

    // حذف العلامات القديمة
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];

    if (properties) {
      properties.forEach(prop => {
        if (prop.location?.lat && prop.location?.lng) {
          const lat = Number(prop.location.lat);
          const lng = Number(prop.location.lng);
          
          const marker = window.L.marker([lat, lng])
            .addTo(mapInstance.current)
            .bindPopup(`
                <div style="text-align:right; direction:rtl; min-width: 150px;">
                    <strong>${prop.type} ${prop.status}</strong><br/>
                    <small>${prop.location.city}</small><br/>
                    <b style="color:#198754">${prop.price?.toLocaleString()} ج</b>
                </div>
            `);
            
          markersRef.current.push(marker);
        }
      });
    }
  };

  useEffect(() => {
    if (mapInstance.current && window.L) {
      updateMarkers();
    }
  }, [properties]);

  useEffect(() => {
    if (mapInstance.current && focusId && properties) {
      const prop = properties.find(p => p.id === focusId);
      if (prop && prop.location?.lat && prop.location?.lng) {
        mapInstance.current.setView([prop.location.lat, prop.location.lng], 15);
        // فتح النافذة المنبثقة للعلامة المحددة يمكن إضافته هنا إذا لزم الأمر
      }
    }
  }, [focusId, properties]);

  const handleLocateMe = () => {
    if (!navigator.geolocation) {
      alert("المتصفح لا يدعم تحديد الموقع الجغرافي.");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        if (!mapInstance.current || !window.L) return;

        const { latitude, longitude } = position.coords;
        const userPos = [latitude, longitude];

        mapInstance.current.setView(userPos, 15);

        if (userMarkerRef.current) {
          userMarkerRef.current.remove();
        }

        userMarkerRef.current = window.L.circleMarker(userPos, {
          radius: 8,
          fillColor: "#0d6efd",
          color: "#fff",
          weight: 2,
          opacity: 1,
          fillOpacity: 0.8
        }).addTo(mapInstance.current).bindPopup("موقعك الحالي").openPopup();
      },
      (error) => {
        alert("تعذر تحديد موقعك. يرجى التحقق من إعدادات الموقع.");
      }
    );
  };

  return (
    <div className="map-container shadow-lg" style={{ height: 'calc(100vh - 200px)', minHeight: '500px', position: 'relative', borderRadius: '15px', overflow: 'hidden' }}>
      <div ref={mapRef} style={{ width: '100%', height: '100%', zIndex: 1 }} />
      <button 
        className="btn btn-light position-absolute shadow-sm"
        style={{ top: '10px', right: '10px', zIndex: 1000, width: '40px', height: '40px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
        onClick={handleLocateMe}
        title="تحديد موقعي"
      >
        📍
      </button>
    </div>
  );
};

export default MapView;
